 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    bars = []
    for edge in (0, h - 1):
        c = 0
        while c < w:
            if grid[edge][c] == bg:
                c += 1
                continue
            color = grid[edge][c]
            lo = c
            while c < w and grid[edge][c] == color:
                c += 1
            bars.append((edge, lo, c - 1))

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and not any(r == edge and lo <= c <= hi
                                                for edge, lo, hi in bars)]
    if not bars or not markers:
        return out
    paint = markers[0][2]

    # Extend each end of every edge bar toward the opposite edge. A marker
    # terminates its ray and is marked as the special endpoint color 4.
    for edge, lo, hi in bars:
        direction = 1 if edge == 0 else -1
        for col in {lo, hi}:
            r = edge + direction
            while 0 <= r < h:
                if grid[r][col] != bg:
                    out[r][col] = 4
                    break
                out[r][col] = paint
                r += direction

    # Markers are endpoints even if they do not happen to lie on a ray.
    for r, c, _ in markers:
        out[r][c] = 4
    return out
